SCRIPT = """<script type='module'>
const root=document.querySelector('.kyra');
if(root){
root.dataset.kyraReady='true';
const plots=root.querySelectorAll('.ky-plot');
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('ky-visible');observer.unobserve(entry.target);}}),{threshold:.25});plots.forEach(plot=>observer.observe(plot));}else plots.forEach(plot=>plot.classList.add('ky-visible'));
root.querySelectorAll('[data-series-toggle]').forEach(button=>button.addEventListener('click',()=>{const on=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(on));root.querySelectorAll('[data-series="'+button.dataset.seriesToggle+'"]').forEach(el=>{el.hidden=!on;el.style.display=on?'':'none';});root.querySelectorAll('.ky-chart-tip').forEach(el=>el.hidden=true);}));
root.querySelectorAll('[data-chart-points]').forEach(input=>input.addEventListener('change',()=>root.querySelectorAll('.ky-point').forEach(el=>el.style.visibility=input.checked?'visible':'hidden')));
root.querySelectorAll('[data-chart-grid]').forEach(input=>input.addEventListener('change',()=>root.querySelectorAll('.ky-gridline').forEach(el=>el.style.visibility=input.checked?'visible':'hidden')));
root.querySelectorAll('.ky-hit').forEach(hit=>{const tip=hit.closest('.ky-plot').querySelector('.ky-chart-tip');const show=()=>{const lines=[hit.dataset.day];root.querySelectorAll('[data-series-toggle][aria-pressed=true]').forEach(button=>lines.push(button.dataset.label+': '+hit.dataset[button.dataset.seriesToggle]));tip.textContent=lines.join(' · ');tip.hidden=false;};hit.addEventListener('pointerenter',show);hit.addEventListener('focus',show);hit.addEventListener('pointerleave',()=>tip.hidden=true);hit.addEventListener('blur',()=>tip.hidden=true);});
root.querySelectorAll('[data-ky-filter]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-ky-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let visible=0;root.querySelectorAll('[data-ky-category]').forEach(card=>{card.hidden=button.dataset.kyFilter!=='all'&&card.dataset.kyCategory!==button.dataset.kyFilter;if(!card.hidden)visible++;});const empty=root.querySelector('[data-filter-empty]');if(empty)empty.hidden=visible>0;}));
}
</script>"""
